<?php require 'bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$id=(int)post('id');if(post('name')===''||mb_strlen(post('name'))>120)throw new RuntimeException('กรุณากรอกชื่อหมวดหมู่ไม่เกิน 120 ตัวอักษร');if(mb_strlen(post('name_en'))>120||mb_strlen(post('description_en'))>10000)throw new RuntimeException('ข้อมูลภาษาอังกฤษยาวเกินกำหนด');if($id)q('UPDATE categories SET name=?,description=?,name_en=?,description_en=?,active=? WHERE id=?',[post('name'),post('description'),post('name_en')?:null,post('description_en')?:null,isset($_POST['active'])?1:0,$id]);else q('INSERT INTO categories(name,description,name_en,description_en,active) VALUES (?,?,?,?,?)',[post('name'),post('description'),post('name_en')?:null,post('description_en')?:null,isset($_POST['active'])?1:0]);flash('บันทึกหมวดหมู่แล้ว การปิดหมวดหมู่จะซ่อนสินค้าที่ผูกอยู่');go('admin/categories.php');}catch(RuntimeException $ex){$error='บันทึกไม่ได้ กรุณาตรวจสอบชื่อหมวดหมู่ที่อาจซ้ำ';}}admin_header('จัดการหมวดหมู่');?><p class="error"><?=e(t($error))?></p><?php $all=q('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON c.id=p.category_id GROUP BY c.id')->fetchAll();$all[]=['id'=>0,'name'=>'','description'=>'','active'=>1,'product_count'=>0];foreach($all as $c):?><form method="post" class="panel"><?=csrf()?><input type="hidden" name="id" value="<?=$c['id']?>"><h2><?=$c['id']?'สินค้าในหมวด: '.$c['product_count']:'เพิ่มหมวดหมู่'?></h2><?php field('name','ชื่อหมวดหมู่ไทย','text',$c['name']);field('name_en','ชื่อหมวดหมู่อังกฤษ (เว้นว่างใช้ต้นฉบับ)','text',$c['name_en']??'',false);?><label><?=e(t('รายละเอียด'))?><textarea name="description"><?=e($c['description'])?></textarea></label><label>รายละเอียดอังกฤษ<textarea name="description_en" maxlength="10000"><?=e($c['description_en']??'')?></textarea></label><label class="checkbox"><input type="checkbox" name="active" <?=$c['active']?'checked':''?>> เปิดใช้งาน</label><button><?=e(t('บันทึก'))?></button></form><?php endforeach;admin_footer();?>
